content:
- **Don't**:
  ```c
  class ExampleClass {
    int LProcLgh;

  	int stringlength( string Value ){
  		LProcLgh= Value.Length();
  		Print ( "String length obtained: "+LProcLgh );
  		return LProcLgh;
  	}
  }
  ```
  **Do**:
  ```c
  class ExampleClass
  {
  	protected int m_iLastProcessedLength;

  	int GetStringLength(string value)
  	{
  		m_iLastProcessedLength = value.Length();
  		Print("String length obtained: " + m_iLastProcessedLength);
  		return m_iLastProcessedLength;
  	}

  	int GetLastProcessedLength()
  	{
  		return m_iLastProcessedLength;
  	}
  }
  ```

- **Don't**:
  ```c
  class ExampleClass
  {
  	protected int m_iLength;

  	int GetStringLength(string name)
  	{
  		m_iLength = name.Length();
  		Print("String length obtained: " + m_iLength);
  		return m_iLength;
  	}
  }
  ```
  **Do**:
  ```c
  class ExampleClass
  {
  	// keeping the variable into method scope and away from the instance

  	int GetStringLength(string name)
  	{
  		int length = name.Length();
  		Print("String length obtained: " + length);
  		return length;
  	}
  }
  ```

- **Don't**:
  ```c
  switch (value)
  {
  	case 0:
  	{
  		Print("0");
  		break;
  	}

  	default:
  	{
  		Print("default");
  		break;
  	}
  }
  ```
  **Do**:
  ```c
  switch (value)
  {
  	case 0:
  		Print("0");
  		break;

  	default:	// brackets are needed only if variables are declared in the 'case' code
  	{			// otherwise scoping is superfluous (and very slightly impacts performance)
  		string message = "default";
  		Print(message);
  		break;
  	}
  }
  ```

- **Don't**:
  ```c
  // this array only lists pointers but does not increase the reference count
  array<ExampleClass> classArray = {};

  ExampleClass newInstance;
  for (int i; i < 10; i++)
  {
  	newInstance = new ExampleClass();
  	classArray.Insert(newInstance);
  	// newInstance will be deleted at the end of the scope
  	// as there are no references to it
  }
  ```
  **Do**:
  ```c
  // this array keeps a strong reference to its items
  array<ref ExampleClass> classArray = {};

  ExampleClass newInstance;
  for (int i; i < 10; i++)
  {
  	newInstance = new ExampleClass();
  	classArray.Insert(newInstance);
  	// classArray keeps a strong reference to newInstance - it will not be cleared
  }
  ```

- **Don't**:
  > **Note:** Here, both ParentClass and ChildClass have a strong reference to each other, keeping the reference count above zero - creating an "island of isolation" (see Scripting: Automatic Reference Counting for more information).

  ```c
  class MainClass
  {
  	ref SubClass m_SubClass;

  	void MainClass()
  	{
  		m_SubClass = new SubClass(this);
  	}
  }

  class SubClass
  {
  	ref MainClass m_Parent;

  	void SubClass(MainClass parent)
  	{
  		m_Parent = parent;
  	}

  	void DoSomething()
  	{
  		Print(m_Parent);
  	}
  }
  ```
  **Do**:
  > **Note:** Here, the MainClass needs the SubClass (it creates it in its constructor meaning it needs it to work) but the subClass does not require MainClass - if the MainClass reference does not exist, it will simply not use it.

  ```c
  class MainClass
  {
  	ref SubClass m_SubClass;

  	void MainClass()
  	{
  		m_SubClass = new SubClass(this);
  	}
  }

  class SubClass
  {
  	MainClass m_Parent; // ref removed

  	void SubClass(MainClass parent)
  	{
  		m_Parent = parent;
  	}

  	void DoSomething()
  	{
  		if (!m_Parent) // null safety check
  			return;

  		Print(m_Parent);
  	}
  }
  ```

## Class Keywords

- **Keyword**: class
  **Description**:
  Declares a class

  ```c
  class ExampleClass
  {
  }
  ```
- **Keyword**: modded
  **Description**:
  See Object Oriented Programming Advanced Usage - Modding.

  ```c
  class ExampleClass
  {
  }

  modded class ExampleClass // inherits and "takes the place" of the original ExampleClass
  {
  }
  ```
- **Keyword**: sealed
  **Description**:
  A class marked with the **sealed** keyword cannot be inherited from

  ```c
  sealed class Infertile
  {
  }

  class Child : Infertile // compilation error - a class cannot inherit from a sealed class
  {
  }
  ```
- **Keyword**: extends
  **Description**:
  states that the declared class inherits from another

  ```c
  class ChildClass extends ParentClass
  {
  }

  // alias
  class ChildClass : ParentClass
  {
  }
  ```
- **Keyword**: typedef
  **Description**:
  Declares an alias for a type

  ```c
  typedef string Text;

  class ExampleClass
  {
  	Text m_sMyText = "This is my text, that is a string";
  }
  ```

## Method Keywords

- **Keyword**: proto
  **Description**: Disclose an engine-side method to script (Engine side).
- **Keyword**: external
  **Description**: Compiler hint to link API methods - only applies to `proto` methods (Engine side).
- **Keyword**: native
  **Description**: Native call convention of internal method (Engine side).
- **Keyword**: volatile
  **Description**: Internal method that may call back to script (hint for compiler that context need to be saved on stack).
- **Keyword**: private
  **Description**:
  Modifier for class method. The method can be called only from inside of the same class' methods. A modded class will still be able to use it (but not its children).

  ```c
  class ExampleClass
  {
  	private void HelloWorld()
  	{
  		Print("Hello there");
  	}

  	void PublicHelloWorld()
  	{
  		HelloWorld(); // works from within the object
  	}
  }

  ExampleClass classInstance = new ExampleClass();
  classInstance.PublicHelloWorld();	// works - calls PublicHelloWorld() that calls HelloWorld()
  classInstance.HelloWorld();			// compilation error - HelloWorld() is private and cannot be accessed
  ```
- **Keyword**: protected
  **Description**:
  Modifier for class method. The method can be called only from inside of class' methods or methods of its extended (children) classes, or a modded class.

  ```c
  class ParentClass
  {
  	protected void HelloWorld()
  	{
  		Print("Hello there");
  	}
  }

  class ChildClass : ParentClass
  {
  	void PublicHelloWorld()
  	{
  		HelloWorld(); // works from within the object
  	}
  }

  ChildClass classInstance = new ChildClass();
  classInstance.PublicHelloWorld();	// works - calls PublicHelloWorld() that calls HelloWorld()
  classInstance.HelloWorld();			// compilation error - HelloWorld() is protected and cannot be accessed

  ParentClass classInstance = new ParentClass();
  classInstance.HelloWorld();			// compilation error - HelloWorld() is protected and cannot be accessed
  ```
- **Keyword**: static
  **Description**:
  Modifier for class method. The method can be called without object pointer, just by ClassName.methodName(). Only static values/methods can be accessed from a static method.

  ```c
  class ExampleClass
  {
  	static void HelloWorld()
  	{
  		Print("Hello there");
  	}
  }

  ExampleClass.HelloWorld();	// works

  ExampleClass classInstance = new ExampleClass();
  classInstance.HelloWorld();	// works
  ```
- **Keyword**: event
  **Description**: Hint for tools that the method should be exposed as Entity script event.
- **Keyword**: override
  **Description**:
  Modifier for class method indicating overriding of base class method. Compiler checks if is method present in base class and if method signature matches.

  ```c
  class ParentClass
  {
  	void HelloWorld()
  	{
  		Print("Hello world");
  	}
  }

  class ChildClass : ParentClass
  {
  	override void HelloWorld()
  	{
  		Print("Hello there");
  	}
  }

  ParentClass parentClassInstance = new ParentClass();
  parentClassInstance.HelloWorld();	// prints "Hello world"

  ChildClass childClassInstance = new ChildClass();
  childClassInstance.HelloWorld();	// prints "Hello there"
  ```

  > **Warning:** Please note that an overridden `static` method uses the object's currently-known class:
  >
  > ```c
  > class ParentClass
  > {
  > 	static int GetAge()
  > 	{
  > 		return 50;
  > 	}
  > }
  >
  > class ChildClass : ParentClass
  > {
  > 	override static int GetAge()
  > 	{
  > 		return 10;
  > 	}
  > }
  >
  > ChildClass child = new ChildClass();
  > ParentClass childAsParent = child;
  > Print(childAsParent.GetAge());	// returns 50
  > Print(child.GetAge());			// returns 10
  > ```
- **Keyword**: sealed
  **Description**:
  Modifier for class method. The method cannot be overridden in derived classes.

  ```c
  class ParentClass
  {
  	sealed void HelloWorld()
  	{
  		Print("Hello there");
  	}
  }

  class ChildClass : ParentClass
  {
  	override void HelloWorld() // compilation error - cannot override a sealed method
  	{
  		Print("Hello world");
  	}
  }
  ```

## Value Keywords

- **Keyword**: owned
  **Description**: Modifier for returning internal methods. Tells the script VM that the returning variable (string or array) must not be released.
- **Keyword**: out
  **Description**:
  Modifier for method parameters. It means that the argument may be changed by the method call.

  ```c
  void Method(out array<string> parameter)
  {
  	parameter = {};
  	parameter.Insert("Hello");
  	parameter.Insert("there");
  }

  // ...

  array<string> myArray = null;
  Method(myArray); // myArray is now { "Hello", "there" }
  ```
- **Keyword**: inout
  **Description**:
  Modifier for method parameters. It means that the argument will be used and may be changed by the method call.

  ```c
  class ExampleClass
  {
  	private ref array<string> m_aOldParameter;

  	void Method(inout array<string> parameter)
  	{
  		m_aOldParameter = parameter;

  		parameter = {};
  		parameter.Insert("Hello");
  		parameter.Insert("there");
  	}
  }

  ExampleClass classInstance = new ExampleClass();

  array<string> myArray = null;
  classInstance.Method(myArray); // myArray is now { "Hello", "there" } and classInstance.m_aOldParameter is referencing myArray's old value
  ```
- **Keyword**: const
  **Description**:
  Declares a constant, that is a value that cannot be modified later.

  ```c
  const string MY_TEXT = "Hello there";

  void Method1()
  {
  	Print(MY_TEXT); // will print "Hello there"
  	MY_TEXT = "General Kenobi"; // compilation error - a constant is set in stone and cannot be modified
  }

  void Method2()
  {
  	const string myUnmodifiableString = "Hello there"; // constant valid for method's scope
  	Print(myUnmodifiableString);
  	myUnmodifiableString = "General Kenobi"; // compilation error
  }
  ```
- **Keyword**: reference
  **Description**: Hint for tools (Material editor) that the value may be used as parameter in material.
- **Keyword**: notnull
  **Description**:
  Modifier for method parameter of class pointer type. It means that the method expect the parameter to never be **null**; if a null value is provided, a VM Exception is raised and the method is not called.

  ```c
  void Method(notnull IEntity entity) // no need to check for "if (!entity)" inside the method
  {
  	entity.DoSomething(); // the argument can be accessed safely
  }

  if (myEntity) // it is still needed to check for null before calling the method
  {
  	Method(myEntity);
  }
  ```
- **Keyword**: private
  **Description**:
  Value can only be accessed from the class/instance methods. Mutually exclusive with "protected".

  ```c
  class ExampleClass
  {
  	private bool m_bIsActive;

  	void SetActive(bool value)
  	{
  		m_bIsActive = value;
  	}
  }

  ExampleClass classInstance = new ExampleClass();
  Print(classInstance.m_bIsActive); // compilation error - m_bIsActive is private and cannot be accessed
  ```
- **Keyword**: protected
  **Description**:
  Value can only be accessed from the class/instance methods or its children. Mutually exclusive with "private".

  ```c
  class ParentClass
  {
  	protected bool m_bProtected;
  	private bool m_bPrivate;

  	void SetPrivate(bool value)
  	{
  		m_bPrivate = value;
  	}
  }

  class ChildClass : ParentClass
  {
  	void SetProtected(bool value)
  	{
  		m_bProtected = value; // works - m_bProtected declaration reaches ChildClass
  	}
  }

  ChildClass childClassInstance = new ChildClass();
  Print(childClassInstance.m_bProtected); // compilation error - m_bProtected is protected and cannot be accessed
  ```
- **Keyword**: static
  **Description**:
  Value belongs to the class and not an instance of it. If public, it can be accessed without object pointer, just by

  ```c
  ClassName.variable
  ```

  ```c
  class ExampleClass
  {
  	static bool bStaticValue;
  	private static bool m_bPrivate; // it is good practice to make it protected/private and have getters/setters instead
  }

  Print(ExampleClass.bStaticValue);	// works
  ExampleClass.bStaticValue = true;	// works

  ExampleClass classInstance = new ExampleClass();
  Print(classInstance.bStaticValue);	// works
  classInstance.bStaticValue = true;	// works
  ```

  > **Warning:** Due to the nature of per-scenario mod loading/unloading, `static` properties **are reset game-wide** on modded scenario start/leave due to game and scripts' entire reload.
- **Keyword**: autoptr
  **Description**: Modifier for class/pointer values. Pointed object will be automatically destroyed upon end of variable lifetime (end of scope, or deletion of class, that contain it). ⓘThis keyword is useless in scripting as all classes inherit `Managed`, therefore are managed by ARC.
- **Keyword**: ref
  **Description**: Strong reference. See Automatic Reference Counting for more information.

## Code Keywords

- **Keyword**: auto
  **Description**:
  Guess the type of the variable. Its usage is **not** recommended (see Best Practices)!

  ```c
  auto myVar = 5; // understood as int myVar = 5

  // but it may have been meant as:
  float myVar = 5;
  ```
- **Keyword**: new
  **Description**:
  Creates an instance of the provided class.

  ```c
  class ExampleClass
  {
  }

  ExampleClass classInstance = new ExampleClass();
  ```

  ```c
  class ExampleClass
  {
  	void ExampleClass(int myValue) // a method named from the class is the constructor
  	{
  		Print(myValue);
  	}
  }

  ExampleClass classInstance = new ExampleClass(5); // needs Constructor-defined arguments
  ```
- **Keyword**: delete
  **Description**:
  Deletes an object and sets all its references to `null`.

  > **Important:** It is not possible to delete an object if there is an external reference to it, like an array.

  ```c
  class ExampleClass
  {
  	void Method()
  	{
  		ReferencedClass obj;
  		if (!obj)
  			Print("obj is null");

  		obj = new ReferencedClass();
  		if (obj)
  			Print("obj is not null");

  		delete obj;
  		if (!obj)
  			Print("obj is null");

  		// everything was fine

  		obj = new ReferencedClass();
  		if (obj)
  			Print("obj is not null");

  		array<ref ReferencedClass> list = {};
  		list.Insert(obj);

  		delete obj; // throws a VM Exception
  	}
  }
  ```
- **Keyword**: thread
  **Description**:
  Creates a script thread from a method.

  > **Important:** - `thread` is to be used in Workbench plugins. In game, use the `GetGame().GetCallQueue().CallLater()` method.
  > - A script thread is not a real thread and member variables are therefore "thread-safe".

  ```c
  class ExampleClass
  {
  	// calling this method will print
  	// "MainMethod start"
  	// "ThreadMethod start",
  	// "MainMethod end"
  	// then 500ms later, "ThreadMethod end"
  	void MainMethod()
  	{
  		Print("MainMethod start");
  		thread ThreadMethod();
  		Print("MainMethod end");
  	}

  	protected void ThreadMethod()
  	{
  		Print("ThreadMethod start");
  		Sleep(500);
  		Print("ThreadMethod end");
  	}
  }
  ```

  **Thread methods are only possible within a threaded method:**

  - `Sleep` takes an integer and waits for the provided amount of milliseconds
  - `Wait` takes a bool condition and holds until the provided condition is true
- **Keyword**: null
  **Description**: A null value.
- **Keyword**: this
  **Description**:
  Refers to the method's object itself.

  ```c
  class ExampleClass
  {
  	void MethodA()
  	{
  		this.MethodB();
  	}

  	void MethodB()
  	{
  		Print("It works");
  	}
  }
  ```

  Since  1.1.0, `this` is supported in static methods and behaves like the current type.

  ```c
  class Gen1
  {
  	static void DoSmth() { Print("A"); }
  }

  class Gen2 : Gen1
  {
  	static override void DoSmth(Widget utility)
  	{
  		Print("B");
  		Print(this); // > Gen2
  	}
  }
  ```
- **Keyword**: super
  **Description**:
  Refers to the **parent** class for the requested variable/method.

  ```c
  class Gen1
  {
  	void Method()
  	{
  		Print("Gen1 method");
  	}
  }

  class Gen2 : Gen1
  {
  	override void Method()
  	{
  		Print("Gen2 method");
  	}
  }

  class Gen3 : Gen2
  {
  	override void Method()
  	{
  		super.Method(); // prints "Gen2 method"
  	}
  }
  ```

  Since  1.1.0, `super` is supported in static methods and behaves like a type.

  ```c
  class Gen1
  {
  	static int a = 33;
  	int b = 42;
  	static void ShowMessage() { Print("A"); }
  }

  class Gen2 : Gen1
  {
  	static override void ShowMessage(Widget utility)
  	{
  		Print("B");
  		Print(super);			// > Gen1
  		Print(super.a);			// > a = 33
  		// Print(super.b); <- error - not a static property
  		super.ShowMessage();	// > "A"
  	}
  }
  ```
- **Keyword**: 1.1.0 vanilla
  **Description**:
  Refers to the **unmodded** version of the modded variable/method.

  ```c
  class ClassA
  {
  	static void Hello()
  	{
  		Print("vanilla");
  	}
  }

  // mod 1 content
  modded class ClassA
  {
  	override static void Hello()
  	{
  		Print("modded 1");
  	}
  }

  // mod 2 content
  modded class ClassA
  {
  	override static void Hello()
  	{
  		super.Hello();
  		vanilla.Hello();
  		Print("modded 2");
  	}
  }

  void Test()
  {
  	ClassA o = new ClassA();
  	o.Hello(); // prints modded 1, vanilla, modded 2
  }
  ```
- **Keyword**: debug
  **Description**:
  Triggers a breakpoint in Script Editor.

  > **Note:** This keyword is currently not highlighted as such in Script Editor.

  ```c
  class MyClass
  {
  	[Attribute(defvalue: "0", desc: "Use breakpoints in Workbench")]
  	protected bool m_bUseBreakpoints;

  	static void Hello()
  	{
  		Print("This is debugging");
  #ifdef WORKBENCH
  		if (m_bUseBreakpoints)
  			debug;
  #endif // WORKBENCH
  	}
  }
  ```

## Code Flow Keywords

- **Keyword**: if
  **Description**:
  verifies a boolean condition. If the condition is true then the code is executed.

  ```c
  void Method(int value = 0)
  {
  	if (value > 50)
  		Print("value is > 50");
  }
  ```
- **Keyword**: else
  **Description**:
  optional, declares code to be executed if the if condition is not met

  ```c
  void Method(int value = 0)
  {
  	if (value > 50)
  		Print("value is > 50");
  	else
  		Print("value is <= 50");
  }
  ```
- **Keyword**: for
  **Description**:
  processes code while the provided condition is met. The syntax is:

  ```c
  for (initialisation; loopCondition; completionCode)
  {
  	// code here
  }
  ```

  ```c
  void MethodA(notnull array<string> words)
  {
  	// for (int i = 0; i < words.Count(); i++) // this if for example's sake; use foreach instead
  	for (int i, count = words.Count(); i < count; ++i) // optimised
  	{
  		Print(words[i]);
  	}
  }

  void MethodB(notnull array<string> words)
  {
  	int i; // auto-initialised to zero
  	int count = words.Count();
  	for (; i < count; i++) // initialisation is optional
  	{
  		Print(words[i]);
  	}
  }

  void MethodC(notnull array<string> words)
  {
  	for (int i, count = words.Count(); i < count;) // so is completionCode
  	{
  		Print(words[i]);
  		i++; // do not forget it!
  	}
  }
  ```
- **Keyword**: foreach
  **Description**:
  processes code for each element of an iterable object (e.g an array). Iteration separator is`:`.

  ```c
  // array example
  void Method(notnull array<string> words)
  {
  	foreach (string word : words)
  	{
  		Print(word);
  	}

  	foreach (int index, string word : words)
  	{
  		PrintFormat("word #%1 is %2", index, word);
  	}
  }
  ```

  ```c
  // map example
  void Method(notnull map<string, int> data)
  {
  	foreach (string key, int value : data)
  	{
  		PrintFormat("Key %1's value is %2", key, value);
  	}
  }
  ```
- **Keyword**: while
  **Description**:
  processes code while condition is met. Beware, as it can lock the program on wrong conditions!

  ```c
  void Method(array<string> words)
  {
  	int i = 0;
  	while (i < words.Count())
  	{
  		Print(words[i]);
  		i++; // do not forget it!
  	}
  }
  ```
- **Keyword**: switch
  **Description**:
  switches the code to execute depending on the condition

  ```c
  void Method(string word)
  {
  	switch (word)
  	{
  		case "Hello":
  			Print("it's Hello");
  			break;

  		case "there":
  			Print("it's there");
  			break;

  		default:
  			Print("it's not interesting.");
  			break;
  	}
  }
  ```
- **Keyword**: continue
  **Description**:
  Used to skip to the next iteration in `for`, `foreach`, `while` loops

  ```c
  class ExampleClass
  {
  	// this method will print 0, 1, 2, 4
  	void Skip3()
  	{
  		for (int i; i < 5; i++)
  		{
  			if (i == 3)
  				continue;

  			Print(i.ToString());
  		}
  	}

  	void MethodB()
  	{
  		foreach (IEntity entity : m_aEntities)
  		{
  			if (!entity)
  				continue;

  			Print(entity);
  		}
  	}
  }
  ```
- **Keyword**: return
  **Description**:
  Exits the method immediately with the provided value if any.

  ```c
  class ExampleClass
  {
  	void PrintHelloThere(bool print)
  	{
  		if (!print)
  			return; // ends here if print is false

  		Print("Hello there");
  	}

  	float GetDistanceNotZero(vector v1, vector v2)
  	{
  		if (v1 == v2)
  			return -1;

  		return vector.Distance(v1, v2);
  	}
  }
  ```

A **value** describes a *data holder*; a value is either a **variable** (that can be changed) or a **constant** (that cannot be changed).

Values are declared in Enfusion with a type, in format `type identifier = value` (the `= value` part being optional). Enforce Script uses strong types, which means a value's type cannot be changed along its lifetime.

## Identifier

An **identifier** is the actual name of a value; it *identifies* the value. The naming rules are:

- an identifier can be composed of ASCII letters, numbers and underscores
- an identifier **must** start with an underscore or a letter (**cannot** start with a number)
- an identifier is **case-sensitive**
- an identifier **cannot be identical to a keyword**

The regular expression to be respected is: `^[a-zA-Z_][a-zA-Z0-9_]*$`

It is *recommended* to write variable identifiers in camelCase, (e.g `aNewVariable`) and constants' in UPPER_CASE (e.g `A_NEW_CONSTANT`). See Scripting: Conventions - Variable for Arma Reforger naming conventions.

```c
int myNumber = 10;
int _myNumber = 10;
int myNUMBER = 10;		// different from myNumber

int 1number = 1;		// wrong - starts with a number
int my#variable = 1;	// wrong - contains a character that is not letter/number/underscore
int auto = 1;			// wrong - the "auto" keyword exists and cannot be replaced
```

## Value Declaration

Declaring a value is done by using a type and an identifier:

```c
int myNumber;	// variable myNumber is declared and auto-initialised to 0

myNumber = 10;	// myNumber is now 10
```

It can also be directly created with a value:

```c
int myNumber = 10;
```

### const

A value can be made **constant**, meaning that it will remain the same along its lifetime.

```c
string value1 = "value";			// value1's value is "value"
const string CONST_VALUE = "value";

value1 = "new value";				// value1 is now "new value"
CONST_VALUE = "new value";			// error: cannot modify a const value
```

An object (array, set, map, other class instance) can be `const` yet still have its values changed - `const` here only keeps the reference and does not "freeze" the object in place.

```c
const ref array<string> STRINGS = {};

STRINGS.Insert("Hello there");		// OK: the array remains the same, its content is changed
STRINGS = null;						// error: cannot modify a const value
```

## Passing a Value

### By Content

```c
// integers (whole numbers) are passed by content
int myVar1 = 33;
int myVar2 = myVar1;	// myVar2 is 33 - it copied myValue1's content
myVar2 = 42;			// myVar2 is now 42, myVar1 is still 33 - they are two different values
```

### By Reference

```c
// arrays (list of values) are passed by reference
array<int> myArray1 = { 0, 1, 2, 3 };
array<int> myArray2 = myArray1;	// myArray2 targets myArray1 object - value is not copied but referenced
myArray2[0] = 99;				// myArray1 is now { 99, 1, 2, 3 };
```

## Types

-
  ```c
  // root prefixes
  bool			m_bValue;
  int				m_iValue;
  float			m_fValue;
  string			m_sValue;
  SCR_EEnum		m_eValue;
  vector			m_vValue;
  array<x>		m_aValue;
  map<x, y>		m_mValue;

  // children use parent's prefix
  ResourceName	m_sResourceName;
  LocalizedString	m_sLocalisedString;
  Curve			m_aCurve;

  // no prefix
  SCR_Class		m_ClassInstance;
  typename		m_ClassTypename;
  set<x>			m_Set;
  Color			m_Color;
  ```

Values can be of various types, listed below.

Notions:

- Passed by: content or reference - see above
- Naming prefix: used in **Object**'s value convention (See conventions): `m_` or `s_` + **prefix** + VariableName (e.g: `m_bPlayerIsAlive = true`)
  > **Note:** No prefix is used for constants in conventions.
- Default value: the default value given when a value is declared without content (e.g: `int value` - the variable here is 0, integer's default value)

- **Incorrect**:
  ```c
  bool variable = true;
  if (variable)
  {
  	variable = "it works!"; // not - variable is and remains a bool
  	Print(variable);
  }
  ```
  **Correct**:
  ```c
  bool variable = true;
  if (variable)
  {
  	string display = "it works!"; // correct
  	Print(display);
  }
  ```

### Primitive Types

| Type name | C++ equivalent | Range | Default value | Size (Bytes) |
| --- | --- | --- | --- | --- |
| int | int32 | -2,147,483,648 through +2,147,483,647 | 0 | 4 |
| float | float | ±1.18E-38 through ±3.402823E+38 | 0.0 | 4 |
| bool | bool | *true* or *false* | false | 4 |
| string | char* | - | "" (empty string) | 8 (pointer) + (length × 1 byte) |
| vector | float[3] | like float | { 0.0, 0.0, 0.0 } | 8 (pointer) + (3 × float) 12* |
| void | void | - | - | - |
| class | Instance* | pointer to any script object | null | 8 |
| typename | VarType* | pointer to type structure | null | 8 |

*the asterisk in C++ means a pointer.

### Bool

Passed by: **value**

Naming prefix: **b**

Default value: **false**

A **bool** is a value that can be either **true** or **false** . For example, `bool result = 10 > 5;` result can either be true or false (here is true, as 10 is greater than 5).

Example:

```c
bool myValue;		// myValue is false
myValue = 10 > 0;	// myValue is true
```

### Integer

Passed by: **value**

Naming prefix: **i**

Default value: **0**

Range: -2,147,483,648 to 2,147,483,647

Description: An **integer** (or int) is a whole number, meaning a value without decimals. It can be positive or negative.

Example:

```c
int myValue;	// myValue is 0
myValue = 20;	// myValue is 20
myValue /= 3;	// myValue is 6: 20 / 3 = 6.666… which gets floored to 6 (and not rounded)
```

### Float

Passed by: **value**

Naming prefix: **f**

Default value: **0.0**

Range: 1.18 E-38 to 3.40 E+38

A **float**, or its full name **floating-point number** is a number that can have decimals.

**Precision** is a matter at hand when working with floats; do not expect exact calculations: `0.1 + 0.1 + 0.1 != 0.3` - rounding would be needed to have the result one can expect.

> **Note:** The further away from 0 the float value is, the less precision it has.
>  For "almost equal" comparison, see `float.AlmostEqual`; the default accepted difference (epsilon) is 0.0001 (1/10000) and can be set for each operation as an optional third argument.

Example:

```c
float myValue;	// myValue is 0 (or 0.0)
myValue = 1;	// myValue is 1 (or 1.0)
myValue /= 3;	// myValue is 0.333333…

float originalValue = 1;
float divisionResult = originalValue/3333;
float result = divisionResult * 3333;
originalValue == result;					// returns false due to floating point precision
float.AlmostEqual(originalValue, result);	// returns true
```

### String

Passed by: **value**

Naming prefix: **s**

Default value: **""** (empty string)

Maximum length: 2,147,483,647 characters

Description: a **string** is a sequence of characters; it supports the following escape characters: `\n` (line return) `\r` (caret return) `\t` (horizontal tabulation) `\\` (antislash) `\"` (double quote).

> **Note:** - A string **cannot** be null
> - String comparison is **case-sensitive**; e.g `"abc" != "ABC"`

Example:

```c
string username;		// username is "" (empty string)
username = "Player 1";	// username is "Player 1";
```

### Enum

Passed by: **value**

Naming prefix: **e**

Default value: 0 (which may **not** exist in the enum)

An **enum** is a value that offers a choice between defined options.

"Behind the curtains" it is also an integer that can be assigned to an int variable.

Examples:

```c
[EnumLinear()]
enum EHealthState
{
	ALIVE,
	INJURED,
	UNCONSCIOUS,
	DEAD,
}

EHealthState healthState;				// healthState is ALIVE (0)
healthState = EHealthState.UNCONSCIOUS;	// healthState is UNCONSCIOUS (2)
int myValue = EHealthState.DEAD;		// valid (3)
```

By default, the first value is equal to 0 and the next values are incremented by 1.

```c
enum EHealthState
{
	ALIVE = 42,
	INJURED,			// equals 43
	UNCONSCIOUS = 50,
	DEAD,				// equals 51
}

EHealthState healthState;				// healthState is 0 (no corresponding enum)
healthState = EHealthState.INJURED;		// healthState is 43 (INJURED)
int myValue = EHealthState.ALIVE;		// 42
```

```c
// an enum value can also be defined through bit shifting for e.g flag usage
enum ELifeStatus
{
	HEALTHY		= 1 << 0, // 1
	HAS_HOUSE	= 1 << 1, // 2
	HAS_FOOD	= 1 << 2, // 4
}
```

### Vector

Passed by: **value**

Naming prefix: **v**

Default value: **{ 0, 0, 0 }**

A **vector** is a type that holds **three** float values. Two vectors can be compared with == for **value** comparison.

Example:

```c
// there are three ways to create a vector
vector myVector0;					// myVector0 is { 0, 0, 0 }
vector myVector1 = { 0, 1.5, 2 };
vector myVector2 = "0 1.5 2";

myVector1 == myVector2;				// true

// editing one of the vector values
vector myVector3 = myVector1;		// copies the value
myVector1 == myVector3;				// true
myVector1[1] = 42;					// myVector1 is now { 0, 42, 2 }
myVector1 == myVector3;				// false

// editing the whole vector
myVector3 = { 0, 42, 2 };			// syntax "0 42 2" works too
myVector1 == myVector3;				// true

// operators work
myVector1 += "0 1 0";
myVector1 -= "0 1 0";
myVector1 *= 3.33;
myVector1 /= 3.33;

// cross product and dot product in one operation
vector crossProduct = vector1 * vector2;
float dotProduct = vector1 * vector2;
auto product = vector1 * vector2;	// product is by default a vector
```

### Array

Passed by: **reference** (dynamic array) or **value** (static array)

Naming prefix: **a** for both

Default value: null (**not** an empty array) or static array filled with default item type value (e.g 0 for int, null for object, etc)

Maximum size: int.MAX

An **array** is a list of values. In Enforce Script, an array can only hold one type of data (defined in its declaration).

There are two types of array in Enfusion:

- dynamic array: "list" that will extend the more items are added
- static array: fixed-size list of items - items can be changed, but the array size cannot

Example:

```c
array<string> dynamicArray = {};
string staticArray[2] = { "Hello", "" };

dynamicArray.Insert("Hello");	// dynamicArray = { "Hello" };
dynamicArray.Insert("");		// dynamicArray = { "Hello", "" };

dynamicArray[1] = "there";		// dynamicArray = { "Hello", "there" };
staticArray[1] = "there";		// staticArray = { "Hello", "there" };

// dynamic/static arrays cannot be directly compared for values; == would compare pointers (a.k.a is it the same array, not the same values)
dynamicArray == staticArray;		// false
dynamicArray[0] == staticArray[0];	// true
dynamicArray[1] == staticArray[1];	// true
```

### Set

Passed by: **reference**

Naming prefix: none

Default value: null (**not** an empty set)

A **set** is a list that ensures uniqueness of values. Due to this uniqueness check, item insertion is slower than for an Array; however, checking if an item is contained is faster.

Example:

```c
set<string> setInstance = new set<string>();

setInstance.Insert("Hello there");
setInstance.Insert("General Kenobi");
setInstance.Insert("Hello there");		// setInstance will still only contain "Hello there" and "General Kenobi"

setInstance.Get(0); // the values order is never guaranteed as it can change on value insertion!
```

### Map

Passed by: **reference**

Naming prefix: **m**

Default value: null (**not** an empty map)

A **map** is a list of key-value pairs, also known as a dictionary. Two keys cannot be identical as they are used to index the values.

A float **cannot** be a map key.

Example:

```c
map<int, string> mapInstance = new map<int, string>();

mapInstance.Set(5712, "Hello there");
mapInstance.Set(5716, "General Kenobi");

mapInstance.Get(5712);	// returns "Hello there"
mapInstance.Get(5715);	// /!\ returns "" (default string)
mapInstance.Get(5716);	// returns "General Kenobi"

mapInstance.GetKeyByValue("Hello there");	// returns 5712
mapInstance.GetKeyByValue("test");			// /!\ returns 0 (default int)

mapInstance.Contains(5716);			// true
mapInstance.ReplaceKey(5716, 5715);	// replaces "General Kenobi" key
mapInstance.Contains(5716);			// false

mapInstance.Contains(5715);	// true
mapInstance.Remove(5715);	// removes "General Kenobi" from the map
mapInstance.Contains(5715);	// false
```

### Class

Passed by: **reference**

Naming prefix: none

Default value: **null**

A **class** is what defines an object's structure - said from the other end, an object is an **instance** of a class.

> **Note:** For more information on classes and Object Oriented Programming, see Object Oriented Programming Basics and Object Oriented Programming Advanced Usage.

Example:

```c
class ObjectClass
{
	protected int m_iHealth = 100;

	int GetHealth()
	{
		return m_iHealth;
	}

	bool SetHealth(int health)
	{
		if (health < 0 || health > 100)
			return false;

		m_iHealth = health;
		return true;
	}
}

void HealthMethod()
{
	ObjectClass myObjectInstance; // myObjectInstance is null
	myObjectInstance = new ObjectClass();
	int objectHealth = myObjectInstance.GetHealth();
	Print(objectHealth);
}
```

### Typename

Passed by: **reference**

Naming prefix: none

Default value: **typename.Empty**

A **typename** is a "class information" type allowing to obtain values and other instance details through reflection.

Example:

```c
class ObjectClass
{
	int m_Health = 100;

	void MyMethod()
	{
		typename myTypename = ObjectClass;
		string myClassName = myTypename.ToString();			// returns "ObjectClass" string
		myTypename = myClassName.ToType();					// returns ObjectClass typename

		int localHealth;
		myTypename.GetVariableValue(this, 0, localHealth);		// localHealth now has m_Health's value

//		typename cannotAssignNull = null;					// throws an error - cannot assign null
		typename canAssignEmpty = typename.Empty;			// good

		string nonExistingClass = "ThisClassDoesNotExist";
		typename wrongTypename = nonExistingClass.ToType();	// returns typename.Empty
		typename uninitialisedTypename;						// is typename.Empty
	}
}
```

## Scope

A value has a lifetime, whether it is the game instance, mission or script duration; but it also has a scope that defines its existence and its accessibility.

```c
void SetDammage(int dammage)
{
	int newHealth;							// newHealth variable is declared
	newHealth = m_iHealth - dammage;
	if (newHealth < 0)
	{
		newHealth = 0;
	}
	else if (newHealth > 100)
	{
		int difference = newHealth - 100;	// difference variable is declared
		Print("health overflow: " + difference);
		newHealth = 100;					// difference variable is destroyed after leaving the "else" scope and doesn't exist outside of it
	}
	// difference variable does not exist in this scope and cannot be used

	m_iHealth = newHealth;					// newHealth variable's last usage - the variable still exists

	Print("Health has been set");			// newHealth is destroyed after this line (on closing the "SetDammage" scope)
}
```

- **Incorrect**:
  ```c
  if (soldiersHealth > 75)
  {
  	string message = "I'm doing well";
  }
  else
  {
  	// no conflict with the previous variable as scopes are different
  	string message = "I don't feel so good";
  }
  Print(message); // error: message variable is undefined here
  ```
  **Correct**:
  ```c
  string message;
  if (soldiersHealth > 75)
  {
  	message = "I'm doing well";
  }
  else
  {
  	message = "I don't feel so good";
  }
  Print(message); // OK
  ```
  **Shorter but more expensive**:
  ```c
  string message = "I don't feel so good";
  if (soldiersHealth > 75)
  {
  	message = "I'm doing well";
  }

  Print(message); // OK
  ```

## Casting

A value can sometimes be returned as one of its inherited classes or interfaced type - it can be **casted** ("forced" into a type) if the underlying type is known.

> **Important:** A wrong cast will return a **null** value - no exception will be thrown.

```c
class Soldier_Base
{
	int m_iScope = 0;
}

class B_Soldier_F : Soldier_Base
{
	int m_iScope = 2;
	void SayHello()
	{
		Print("Hello there");
	}
}

Soldier_Base aSoldier = new B_Soldier_F(); // valid
aSoldier.SayHello(); // invalid - Soldier_Base does not have the SayHello method

B_Soldier_F mySoldierF = B_Soldier_F.Cast(aSoldier);
mySoldierF.SayHello(); // valid
```

**Automatic Reference Counting**, shortened to **ARC**, is a memory management solution used in Enforce Script. Enforce Script does not use Garbage Collection (a.k.a GC). In comparison with the widely used Tracing garbage collection (in e.g C#, Java):

- it does not suffer from cleanup stuttering (lags due to high GC load)
- memory management performance is not dependent on the number of managed instances
- it is simple to implement (having a good working GC is a big issue)

On the negative side, it is open to the cyclic reference problem, described in the Cyclic Reference paragraph below.

> **Note:** This whole system impacts **objects** passed by **reference** - see Value Types.

## Principle

Enfusion has an internal counter of strong references to objects; when this counter reaches 0, the object is released from memory.

> **Warning:** Reference only makes sense with `Managed` objects; using `ref` with a *value type* (e.g `ref vector` or `ref int`) is incorrect!

### Strong Reference

A strong reference is a reference to an object that increments the reference counter. The referenced object **cannot** become null during the referencing object's lifetime unless manually deleted (with the `delete` keyword).

> **Important:** Strong references:
>
> - using the `ref` keyword
> - scope lifetime's script reference
>
> References to local variables in methods are already strong, so using `ref` in methods is redundant:
>
> - **Do**:
>   ```c
>   void Method(int a, int b, int c)
>   {
>   	array<int> numbers = { a, b, c }; // yes
>   	foreach (int number : numbers)
>   	{
>   		Print(number);
>   	}
>   }
>   ```
>   **Don't**:
>   ```c
>   void Method(int a, int b, int c)
>   {
>   	ref array<int> numbers = { a, b, c }; // no
>   	foreach (int number : numbers)
>   	{
>   		Print(number);
>   	}
>   }
>   ```

### Weak Reference

A weak reference is a reference to an object that does not increment the reference counter. The reference may become null during the program's lifetime.

## Usage

```c
class ExampleClass
{
	// weak reference to an object
	ReferencedClass m_WeakRefObject;

	// strong reference to an object
	ref ReferencedClass m_StrongRefObject;

	// strong reference to a dynamic array (that is an object itself) of weak references
	ref array<ReferencedClass> m_aWeakRefArray;

	// strong reference to dynamic array of strong references
	ref array<ref ReferencedClass> m_aStrongRefArray;

	// static array of strong references
	ref ReferencedClass m_aStrongRefStaticArray[10];

	// maps and sets work the same
	ref map<string, ReferencedClass> m_mWeakRefMap;
	ref map<string, ref ReferencedClass> m_mStrongRefMap;
	ref set<ReferencedClass> m_WeakRefSet;
	ref set<ref ReferencedClass> m_StrongRefSet;

	void Method()
	{
		ReferencedClass localReference = new ReferencedClass();
		localReference = new ReferencedClass();	// the previous object loses its strong reference and is immediately released
												// the newly created object replaces it

		array<ReferencedClass> arrayOfWeakRef = new array<ReferencedClass>(); // array of weak references is created
		arrayOfWeakRef.Insert(new ReferencedClass());
		// ReferencedClass object is created and immediately deleted, as arrayOfWeakRef does not increment the reference counter

		array<ref ReferencedClass> arrayOfStrongRef = new array<ref ReferencedClass>(); // array of strong references is created
		arrayOfStrongRef.Insert(new ReferencedClass()); // ReferencedClass object is created and kept

		// at the end of the method, local variables 'localReference', 'arrayOfWeakRef' and 'arrayOfStrongRef' are released:
		// localReference is destroyed
		// arrayOfWeakRef is destroyed (it only contains NULL),
		// arrayOfStrongRef is destroyed (it contains the last strong ref to object, so its contained object is destroyed as well
	}
}
```

### Cyclic Reference

#### Problem

The main issue with reference counting is cyclic references (aka "Island of isolation"). In the code below:

- the main method creates object A and object B
- object A references object B
- object B references object A
- the main method ends, dropping its references to object A and B
- both objects a and b should be deleted but they still reference each other, keeping the reference counting above 0:
  - any reference to them is lost after main method's ending
  - they remain in memory until the program is stopped

```c
class Parent
{
	ref Child m_Child;
}

class Child
{
	ref Parent m_Parent;
}

void Function()
{
	Parent a = new Parent();	// 'a' has 1 reference
	Child b = new Child();		// 'b' has 1 reference
	a.m_Child = b;				// 'b' has 2 references
	b.m_Parent = a;				// 'a' has 2 references

	// local variables 'a', 'b' are released (reference count is decreased by 1)
	// both objects remain in memory, having 1 reference each (each other)
}
```

#### Solution

The solution to this issue is to have one object have a strong reference, while the other only holds a weak one:

```c
class Parent
{
	ref Child m_Child;
}

class Child
{
	Parent m_Parent;
}

void Function()
{
	Parent a = new Parent();	// 'a' has 1 strong (scope) reference
	Child b = new Child();		// 'b' has 1 strong (scope) reference
	a.m_Child = b;				// 'b' has 2 strong references
	b.m_Parent = a;				// 'a' has 1 strong reference, 1 weak reference

	// local variables 'a', 'b' are released (reference count is decreased by 1)
	// a only has 1 weak reference and is released from memory
	// b loses a's reference and has no more reference to it - it gets released
}
```

Using weak references makes null-checking take more importance in scripting.

> **Note:** Format reminder:
>
> - **camelCase** is writing by gluing words together and making their first letter capital, but for the first one, e.g `namingLikeThis`.
> - **PascalCase** is writing in **camelCase** but with the first letter set uppercase, e.g `NamingLikeThis`.
> - **snake casing** (`naming_like_this`) is **not** a convention used in Enfusion.
> Only `const` values should be `NAMED_LIKE_THIS`.

## Tag

To prevent conflict with other scripts all classes, and global functions must be distinguished by a Tag.

Bohemia Interactive scripts have been prefixed with `SCR_`. A mod developer must choose their own tag and not use one already taken by Bohemia Interactive or another developer.

When modding any class, all methods and variables within that modded class must also be distinguished by the same unique tag to prevent conflict.

## File/Class

- File should be called `TAG_MyObject.c`
  - A component must end with "component": `TAG_ExampleComponent.c`
  - An entity must end with "entity': `TAG_ExampleEntity.c`
- Class should be called the same (without file extension):
  - `class TAG_MyObject`
  - `class TAG_ExampleComponent`
  - `class TAG_ExampleEntity`
- Enum:
  - name must be prefixed with a capital E, e.g `TAG_EMyEnum`
  - values use all capital letters with words separated by underscores, e.g `TAG_EMyEnum.VALUE_1`
- The file should be located in the `scripts\Game` directory
- The use of plural is prohibited at the end of combined keywords: e.g `TAG_NotificationsComponent` → `TAG_NotificationComponent`

## Method

- **Functions**/**Methods** naming uses **PascalCase**, e.g:
  ```c
  int ReturnNumber()
  ```
- Parameters are named with **camelCase**, e.g:
  ```c
  int ReturnNumber(bool canBeNegative)
  ```

## Variable

-
  ```c
  // root prefixes
  bool			m_bValue;
  int				m_iValue;
  float			m_fValue;
  string			m_sValue;
  SCR_EEnum		m_eValue;
  vector			m_vValue;
  array<x>		m_aValue;
  map<x, y>		m_mValue;

  // children use parent's prefix
  ResourceName	m_sResourceName;
  LocalizedString	m_sLocalisedString;
  Curve			m_aCurve;

  // no prefix
  SCR_Class		m_ClassInstance;
  typename		m_ClassTypename;
  set<x>			m_Set;
  Color			m_Color;
  ```

> **Note:** See Scripting: Values - Identifier for more information.

- **Member** variables are prefixed with `m_`, a one-letter type prefix for specific types (see Value types), and use **PascalCase**, e.g:
  ```c
  IEntity m_Entity;
  int m_iHealth;
  bool m_bIsEnemy;
  ```
- **Global** variables are prefixed with `g_`.
  > **Important:** Global variables are bad practice and must not be used outside of absolute necessity!
- **Static** variables are prefixed with `s_` (**constants** are not), eventually a one-letter type prefix, and use **PascalCase**, e.g
  ```c
  protected static int s_iUnitsCount;
  ```
- **Local** variables and **arguments** (method parameters) use **camelCase**, e.g:
  ```c
  void MethodA()
  {
  	int value = 42;
  	string name = "John";

  	float result = MethodB(value, name);
  }
  ```
- **Constant** values use **all capital letters** with words separated by **underscores** (uppercase snake casing), e.g:
  ```c
  const int MAX_VALUE = 9999;		// no 'm_' prefix nor 'i' type prefix
  static const int TOTAL = 10;	// no 's_' prefix either
  ```

### Order

- First go **Attributes** (if any),
- then public, protected, private **member variables**
- then public, protected, private **static variables**
- then public, protected, private **constants**

```c
[Attribute()]
protected int m_iAttribute;

int m_iPublic;
protected int m_iProtected;
private int m_iPrivate;

static int s_iPublic;
protected static int s_iProtected;
private static int s_iPrivate;

static const int PUBLIC;
protected static const int PROTECTED;
private static const int PRIVATE;
```

## Script

### General

- Curly braces must always be on a new line - Enforce Script uses **Allman style**
- Variables and functions should be **`protected`** whenever possible (respecting OOP black box principle) unless they are **intended** to be exposed
- **Getters**/**Setters**: variables should be made `protected` and accessed through getters and setters (entry methods getting/setting the value)

```c
class SCR_HumanComponent : ScriptComponent
{
	protected int m_iAge;

	void SetAge(int age)
	{
		m_iAge = age;
		PrintFormat("Age of instance %1 is now %2", this, m_iAge);
	}

	int GetAge()
	{
		return m_iAge;
	}
}
```

### Spacing

- **Tabs** are used for indentation - they are set to a size of **4 spaces** in Script Editor
- A space is used before and after:
  - a binary operator
  - a `foreach` colon
  - a class' inheritance colon
- A space is used after:
  - `if`, `for`, `foreach`, `switch`, `while` keywords
  - a `for` semicolon
- Spaces are used inside parentheses but not around their content

```c
class SCR_HumanComponent : ScriptComponent
{
	if (true)
	{
	}

	for (int i = 0; i < 10; i++)
	{
	}

	foreach (string item : stringArray)
	{
	}

	switch (value)
	{
		case 42:
			break;
	}

	while (true)
	{
		break; // in case of a hasty copy-paste :)
	}
}
```

### Method

- All methods must be separated using this sequence of characters: two slashes followed by 96 dashes (see Example)
  ```c
  //------------------------------------------------------------------------------------------------
  ```
- **Documentation** must be done with Doxygen support in mind, using the `//!` comment syntax (see Example)
- Methods should be **sorted** in the following order (top to bottom):
  - General methods
  - EOnFrame
  - EOnInit
  - Constructor
  - Destructor

```c
//! A scripted entity
class SCR_ScriptedEntity : GenericEntity
{
	//------------------------------------------------------------------------------------------------
	//! Get the normalized direction vector at position A pointing to B
	//! \param vectorA First position, direction origin
	//! \param vectorB Second position, direction goal
	//! \return The direction from A to B as a normalized vector
	protected vector GetNormalizedDirection(vector vectorA, vector vectorB)
	{
		vector dir = vectorB - vectorA;
		return dir.Normalized();
	}

	//------------------------------------------------------------------------------------------------
	//! Frame
	override void EOnFrame(IEntity owner, float timeSlice)
	{
		vector direction = GetNormalizedDirection(owner.GetOrigin(), vector.Zero);
		Print("OnFrame was called! Direction: " + direction);
	}

	//------------------------------------------------------------------------------------------------
	//! Init
	override void EOnInit(IEntity owner)
	{
		Print("Init was called!");
	}

	//------------------------------------------------------------------------------------------------
	// constructor
	void SCR_ScriptedEntity(IEntitySource src, IEntity parent)
	{
		SetEventMask(EntityEvent.INIT | EntityEvent.FRAME | EntityEvent.CONTACT);
	}

	//------------------------------------------------------------------------------------------------
	// destructor
	void ~SCR_ScriptedEntity()
	{
		Print("Destructing SCR_ScriptedEntity");
	}
}
```

### Miscellaneous

- class instanciation with the `new` keyword **must** use parentheses:
  ```c
  SCR_Class myClass = new SCR_Class();			// correct
  SCR_Class myClass = new SCR_Class;				// wrong
  ```
- arrays can be initialised directly:
  ```c
  array<string> myArray = {};						// correct
  array<string> myArray = new array<string>();	// tolerable
  array<string> myArray = new array<string>;		// wrong
  ```

## Moddability

It is important to keep moddability in mind when scripting to ensure. Modded classes work very similar to inherited ones and come with the same restrictions:

- **Constructor/Destructor**: a modded class has its own const/destructor and cannot modify the parent one
- **Private variables & methods**: a modded class cannot override parent's private members - use `protected` instead of `private`
- **Static variables & methods**: same as above - do not use unless absolutely necessary
- **Global methods**: no classes to mod - do not use unless absolutely necessary.

## Example

```c
[EntityEditorProps("GameScripted/SomeFolder", "Description of this component", "255 0 0 255", true, true, "", "box", "-0.25 -0.25 -0.25", "0.25 0.25 0.25", "0 0 0 0")]
class SCR_SomeComponentClass
{
}

SCR_SomeComponentClass SCR_SomeComponentSource;

//! Flags used for an entity to define its currently active components.
enum SomeFlags
{
	MESH = 1,
	BODY = 2,
	HIERARCHY = 4,
	NET = 8,
}

//! A brief explanation of what this component does.
//! The explanation can be spread across multiple lines.
//! This should help with quickly understanding the script's purpose.
class SCR_SomeComponent : ScriptComponent
{
	//! Defines the maximum distance at which this object will be rendered in metres.
	[Attribute("30.0", UIWidgets.Slider, "The maximum distance at which this object will be rendered in metres.", "0 120 0.1")]
	protected float m_fRenderDistance;

	//! Maximum count of children that can be spawned at any time. If the limit is exceeded no more children are spawned.
	[Attribute("100", desc: "Maximum count of children that can be spawned at any time. If the limit is exceeded no more children are spawned.", "0 500")]
	protected int m_iMaximumChildCount;

	//! The offset of this object in metres.
	protected vector m_vPositionOffset = "0 0 0";

	//! A public variable
	float m_fSomethingPublic = 3.2;

	//! A public vector
	vector m_vOtherPublic = "1 2 3";

	//! Defines the minimum distance (in metres) for this object to render. If below this value, object will be culled.
	const float RENDER_DISTANCE_MINIMUM = 10;

	//! Defines the maximum distance (in metres) for this object to render. If above this value, object will be culled.
	const float RENDER_DISTANCE_MAXIMUM = 100;

	//------------------------------------------------------------------------------------------------
	//! Returns the render distance of this object (metres).
	float GetRenderDistance()
	{
		return m_fRenderDistance;
	}

	//------------------------------------------------------------------------------------------------
	//! Set the render distance of this object.
	//! \param renderDistance distance in metres. Is clamped between RENDER_DISTANCE_MINIMUM and RENDER_DISTANCE_MAXIMUM.
	void SetRenderDistance(float renderDistance)
	{
		m_fRenderDistance = Math.Clamp(renderDistance, RENDER_DISTANCE_MINIMUM, RENDER_DISTANCE_MAXIMUM);
	}

	//------------------------------------------------------------------------------------------------
	//! Prints hello to the debug console. Protected method, not exposed to outside classes but available to child classes.
	protected void SayHello()
	{
		string localString = "Hello!";
		Print(localString);
	}

	//------------------------------------------------------------------------------------------------
	//! Compare two integers, return the larger one. (Don't mind the silly documentation, mind the syntax)
	//! \param a first parameter to be compared with the second one
	//! \param b second parameter to be compared with the first one
	//! \return true if a is equal to b, false otherwise.
	bool AreEqual(int a, int b)
	{
		// can be simplified to "return a == b;"
		if (a == b)
			return true;
		else
			return false;
	}

	//------------------------------------------------------------------------------------------------
	override void EOnInit(IEntity owner)
	{
		Print("Initialized some component!");
	}

	//------------------------------------------------------------------------------------------------
	// constructor - remove if empty
	void SCR_SomeComponent(IEntityComponentSource src, IEntity ent, IEntity parent)
	{
		ent.SetEventMask(EntityEvent.INIT);

		// If offset is 0, no need to update
		if (m_vPositionOffset != "0 0 0")
		{
			// Get current transformation matrix, add the position offset and update transformation.
			vector mat[4];
			ent.GetTransform(mat);
			mat[3] = mat[3] + m_vPositionOffset;
			ent.SetTransform(mat);
